const tabId = 2023077191;
const iframeContent = await browserjs(tabId, () => {
  const f = document.querySelector('iframe[title*="challenge"]');
  if (!f) return "No challenge iframe found";
  try {
    const doc = f.contentDocument || f.contentWindow.document;
    const table = doc.querySelector('table');
    const cells = Array.from(doc.querySelectorAll('td')).map(td => {
      const rect = td.getBoundingClientRect();
      return {
        className: td.className,
        rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
      };
    });
    const verifyBtn = doc.querySelector('#recaptcha-verify-button, button.rc-button-default');
    return {
      title: doc.title,
      cellCount: cells.length,
      cells,
      verifyBtn: verifyBtn ? verifyBtn.textContent.trim() : null
    };
  } catch (e) {
    return { error: e.message };
  }
});
console.log("Iframe content:", JSON.stringify(iframeContent, null, 2));

